git show -U0 --format='' 3394388e -- 'packages' | awk '
  /^diff --git/ { f=$0; src = (f ~ /\/src\//); next }
  !src { next }
  /^@@/ { next }
  /^(\+\+\+|---)/ { next }
  /^[+-]/ {
    line=$0
    # strip leading +/-
    body=substr(line,2)
    if (body ~ /^[[:space:]]*#\[/) next
    if (body ~ /^[[:space:]]*use Vaulter\\Attributes\\/) next
    if (body ~ /@internal/) next
    # also skip blank
    if (body ~ /^[[:space:]]*$/) next
    print f
    print line
  }
' | head -400
echo "===== COUNT ====="
git show -U0 --format='' 3394388e -- 'packages' | awk '
  /^diff --git/ { f=$0; src = (f ~ / b\/packages\/[^ ]+\/src\//); if (src) files++; next }
  !src { next }
  /^@@/ { next }
  /^(\+\+\+|---)/ { next }
  /^[+-]/ {
    body=substr($0,2)
    if (body ~ /^[[:space:]]*#\[/) next
    if (body ~ /^[[:space:]]*use Vaulter\\Attributes\\/) next
    if (body ~ /@internal/) next
    if (body ~ /^[[:space:]]*$/) next
    c++
    # classify
    if (body ~ /^[[:space:]]*\*/) doc++
    else if (body ~ /^[[:space:]]*\/\*\*/) doc++
    else if (body ~ /^[[:space:]]*\//) doc++
    else code++
  }
  END { print "nonattr", c, "doc-ish", doc+0, "other", code+0, "src files touched check done" }
