            files.append(os.path.join(dp, fn))

attr_re = re.compile(r"#\[(Api|Internal|Spi)\b")
decl_re = re.compile(r"\b(class|interface|trait|enum)\s+(\w+)")
use_trait_re = re.compile(r"^\s+use\s+([^;]+);", re.M)

types = {}  # fqn -> {kind, surface, file, traits}
ns_re = re.compile(r"^namespace\s+([^;]+);", re.M)

for path in files:
    src = open(path, encoding="utf-8", errors="replace").read()
    # split by declarations roughly: find positions
    ns = ns_re.search(src)
    namespace = ns.group(1).strip() if ns else ""
    # walk lines to associate nearest preceding attribute
    lines = src.splitlines()
    pending = []
    i = 0
    while i < len(lines):
        line = lines[i]
        m = attr_re.search(line)
        if m and not line.strip().startswith("//") and not line.strip().startswith("*"):
            pending.append(m.group(1))
        dm = re.search(r"\b(class|interface|trait|enum)\s+(\w+)", line)
        if dm and not line.strip().startswith("*") and not line.strip().startswith("//"):
            name = dm.group(2)
            fqn = f"{namespace}\\{name}" if namespace else name
            # look ahead a bit for trait uses until next method/const or closing at brace depth
            body = "\n".join(lines[i:i+80])
            traits = []
            # only the class body start
            um = re.search(r"\{([\s\S]{0,1500})", body)
            if um:
                chunk = um.group(1)
                # stop at first function/const/public
                chunk = re.split(r"\n\s*(public|protected|private|const|function|#\[)", chunk, maxsplit=1)[0]
                for u in re.finditer(r"^\s+use\s+([^;{]+);", chunk, re.M):
                    traits.append(u.group(1).strip())
            types[fqn] = {"kind": dm.group(1), "surface": pending[-1] if pending else None, "file": path, "traits": traits, "all_pending": list(pending)}
            pending = []
        if line.strip() == "" or line.strip().startswith("namespace") or line.strip().startswith("use ") or line.strip().startswith("<?"):
            pass
        elif not m and dm is None and not line.strip().startswith("#["):
            # reset pending if we passed non-attribute code that's not blank... careful with docblocks
            if line.strip().startswith("/**") or line.strip().startswith("*") or line.strip().startswith("*/") or line.strip().startswith("//"):
                pass
            else:
                pending = []
        i += 1

# map short and fqn
by_short = {}
for fqn, t in types.items():
    by_short.setdefault(fqn.split("\\")[-1], []).append(fqn)

internal_traits = {fqn for fqn,t in types.items() if t["kind"]=="trait" and t["surface"]=="Internal"}
api_traits = {fqn for fqn,t in types.items() if t["kind"]=="trait" and t["surface"]=="Api"}
print("internal traits", len(internal_traits))
print("api traits", len(api_traits))
for fqn in sorted(api_traits):
    print(" API trait", fqn, types[fqn]["file"])

hits = []
for fqn, t in types.items():
    if t["surface"] not in ("Api", "Spi"):
        continue
    for tr in t["traits"]:
        # resolve
        cands = []
        name = tr.split(",")[0].strip().split(" ")[0]
        if name.startswith("\\"):
            cands = [name[1:]]
        elif "\\" in name:
            cands = [name]
        else:
            cands = by_short.get(name, [])
            # also same namespace
            cands = cands + [types[fqn]["file"] and (fqn.rsplit("\\",1)[0] + "\\" + name)]
        for c in cands:
            if c in internal_traits:
                hits.append((fqn, t["surface"], name, c, t["file"]))
print("Api/Spi uses Internal trait:", len(hits))
for h in hits[:40]:
    print(" ", h)

# also Api uses any trait
uses = [(fqn, t["traits"], t["file"]) for fqn,t in types.items() if t["surface"] in ("Api","Spi") and t["traits"]]
print("Api/Spi with any trait use:", len(uses))
for u in uses[:30]:
